"""Run with .venv/bin/python. Downloads only pinned build inputs, not game data."""
import hashlib
import subprocess
from pathlib import Path
import urllib.request

ROOT = Path(__file__).resolve().parent.parent
FILES = {
    'cJSON.c': '298581a04a36c0165da4b0aade235c23088cb2faa58651d720ea2f3706ed0b0d',
    'cJSON.h': '25b0145150d500498e4d209cec69c18c42cf818bffcc54690be3b895a2a16dee',
    'LICENSE': 'a36dda207c36db5818729c54e7ad4e8b0c6fba847491ba64f372c1a2037b6d5c',
}
for name, expected in FILES.items():
    destination = ROOT / '.deps/cjson' / name
    destination.parent.mkdir(parents=True, exist_ok=True)
    data = destination.read_bytes() if destination.exists() else urllib.request.urlopen(f'https://raw.githubusercontent.com/DaveGamble/cJSON/v1.7.19/{name}', timeout=30).read()
    if hashlib.sha256(data).hexdigest() != expected:
        raise SystemExit(f'Checksum mismatch: {name}')
    destination.write_bytes(data)
    print(f'Verified cJSON v1.7.19/{name}')
# elfldr (GPL-3.0-or-later, ps4-payload-dev/elfldr) at a4817404, the v0.7 release plus firmware
# 13.52, 14.00 and a guarded 14.02 kernel-init path. Orbit starts it through GoldHEN's payload
# loader when no ELF loader answers on 9021 (backend/loader_start.c). The SDK image builds it
# (tools/Dockerfile.sdk.ps4); this copies both ELF and BinLoader artifacts out and validates them.
ELFLDR = ROOT / '.deps/elfldr/elfldr.elf'
ELFLDR_BIN = ROOT / '.deps/elfldr/elfldr.bin'
SDK_IMAGE = 'orbit-sdk-ps4:0.9-fw1402'
ELFLDR.parent.mkdir(parents=True, exist_ok=True)

def image_file(name):
    try:
        return subprocess.run(['docker', 'run', '--rm', '--network', 'none', '--entrypoint', 'cat',
                               SDK_IMAGE, f'/opt/elfldr/{name}'],
                              check=True, capture_output=True).stdout
    except (OSError, subprocess.CalledProcessError):
        raise SystemExit(f'elfldr: build {SDK_IMAGE} first: '
                         f'docker build -f tools/Dockerfile.sdk.ps4 -t {SDK_IMAGE} .')

# Always copy both artifacts from the just-built, pinned SDK image so stale
# pre-14.02 outputs cannot survive a rebuild.
elf_data = image_file('elfldr.elf')
if len(elf_data) < 64 or elf_data[:6] != b'\x7fELF\x02\x01':
    raise SystemExit('Invalid elfldr.elf: missing ELF64 header')
ELFLDR.write_bytes(elf_data)

# GoldHEN's BinLoader accepts the raw bootstrap generated by elfldr's pinned Makefile.
bin_data = image_file('elfldr.bin')
if len(bin_data) < 64 or len(bin_data) > 16 * 1024 * 1024:
    raise SystemExit('Invalid elfldr.bin: unexpected size')
ELFLDR_BIN.write_bytes(bin_data)
print('Built guarded 14.02 elfldr:', hashlib.sha256(elf_data).hexdigest())
print('Built GoldHEN bootstrap:', hashlib.sha256(bin_data).hexdigest())
ca = ROOT / '.deps/cacert.pem'
if not ca.exists():
    ca.write_bytes(urllib.request.urlopen('https://curl.se/ca/cacert.pem', timeout=30).read())
if b'-----BEGIN CERTIFICATE-----' not in ca.read_bytes():
    raise SystemExit('CA bundle is invalid')
print('CA SHA-256:', hashlib.sha256(ca.read_bytes()).hexdigest())
